            layer.chunks.push(TileChunk { coord, cells: BTreeMap::new() });
            layer.chunks.last_mut().expect("just pushed")
        };
        chunk.set(local, tile);
        Ok(coord)
    }
    pub fn cancel(self) -> TileMapDocument { self.before }
